SELECT id, customer_id, plan, start_date, monthly_fee, MIN(monthly_fee) OVER (PARTITION BY plan ORDER BY start_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_min_monthly_fee, AVG(monthly_fee) OVER (PARTITION BY plan ORDER BY start_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_avg_monthly_fee, COUNT(monthly_fee) OVER (PARTITION BY plan ORDER BY start_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS last4_count_monthly_fee FROM subscriptions WHERE MONTH(start_date) IN (1, 9, 11);
